(() => {
  const items = [];
  document.querySelectorAll('tr.athing').forEach(row => {
    const id = row.id;
    const titleEl = row.querySelector('.titleline > a');
    const title = titleEl?.innerText || '';
    const sub = row.nextElementSibling;
    const commentsEl = sub?.querySelector('a[href="item?id=' + id + '"]:last-child');
    let commentsText = commentsEl?.innerText || '';
    // More robust: find any subtext link ending with comments
    const links = [...(sub?.querySelectorAll('a') || [])];
    const commentLink = links.find(a => /comments|discuss/.test(a.innerText) && a.href.includes('item?id='));
    if (commentLink) commentsText = commentLink.innerText;
    const points = sub?.querySelector('.score')?.innerText || '';
    items.push({id, title, points, commentsText, url: titleEl?.href});
  });
  return items.filter(x => /^Ask HN:/i.test(x.title));
})()

(() => {
  const rows = [...document.querySelectorAll('tr.athing')];
  const items = rows.map(row => {
    const id = row.id;
    const titleEl = row.querySelector('.titleline > a, .storylink');
    const title = titleEl?.textContent?.trim() || '';
    const sub = row.nextElementSibling;
    const links = [...(sub?.querySelectorAll('a') || [])];
    const commentLink = links.find(a => a.getAttribute('href') === `item?id=${id}` && /comment|discuss/i.test(a.textContent));
    const commentsText = commentLink?.textContent?.trim() || '';
    const comments = commentsText === 'discuss' ? 0 : (parseInt(commentsText.replace(/\D/g, ''), 10) || 0);
    return {id, title, comments, commentsText, itemUrl: `https://news.ycombinator.com/item?id=${id}`};
  });
  const ask = items.filter(x => /^Ask HN:/i.test(x.title));
  ask.sort((a,b) => b.comments - a.comments);
  return {count: ask.length, top: ask[0] || null, ask, allTitles: items.map(x => x.title)};
})()

